/**
 * Golden contract for the SM-18 format-write port follow-up on `.sub` files
 * (sm18-re gitlab #47).
 *
 * The fixture `test/fixtures/sm18-port-format-write-sub.json` is a
 * byte-for-byte mirror of
 * `sm18-re:tests/fixtures/port-format-write-sub.json`, generated by
 * `sm18-re:scripts/export-port-format-write-sub-fixture.py` on the sample
 * collection "ABC of SuperMemo 18". The lane re-copies the mirror on every
 * fixture change so sm18-re's gate catches drift on either side.
 *
 * This file is brief-writer owned. The lane implements two new exports in
 * `src/sm18-format-write.ts`:
 *
 *   writeSub(header: Uint8Array, records: SubRecord[]): Uint8Array
 *   export const SUB_HISTORY_CAP = 1000
 *
 * `writeSub` is a transliteration of `smfmt.sub.write` /
 * `smfmt.info_subs.write`: both globs share the same layout - a headerless
 * little-endian `uint32` array of 1-based element numbers - and both Python
 * writers delegate to `smfmt.sub.write_sub`. The TS writer must reject a
 * non-empty `header` the same way the Python references do, and must
 * reproduce the stored bytes byte-for-byte from the record list.
 *
 * `SUB_HISTORY_CAP` mirrors `smfmt.info_subs.HISTORY_CAP`. The constant is
 * exported so downstream callers that enforce the saturation on
 * `info/history.sub` writes can take the authority from one place; the
 * harness only asserts the value matches the fixture header.
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const FIXTURE_PATH = join(
  __dirname,
  "fixtures",
  "sm18-port-format-write-sub.json",
);
const MODULE_SPEC = ["..", "src", "sm18-format-write.ts"].join("/");

interface SubRecord {
  element_id: number;
}

interface FixtureFile {
  path: string;
  byte_length: number;
  header_b64: string;
  record_count: number;
  element_ids: number[];
  kind: string | null;
  expected_bytes_b64: string;
}

interface Fixture {
  schema: number;
  collection: string;
  scope: string[];
  history_cap: number;
  files: FixtureFile[];
}

interface PortModule {
  writeSub: (header: Uint8Array, records: SubRecord[]) => Uint8Array;
  SUB_HISTORY_CAP: number;
}

async function loadPort(): Promise<PortModule | null> {
  try {
    const mod = await import(MODULE_SPEC);
    if (
      typeof mod?.writeSub !== "function" ||
      typeof mod?.SUB_HISTORY_CAP !== "number"
    ) {
      return null;
    }
    return mod as PortModule;
  } catch {
    return null;
  }
}

function decodeBase64(encoded: string): Uint8Array {
  return new Uint8Array(Buffer.from(encoded, "base64"));
}

function bytesEqual(a: Uint8Array, b: Uint8Array): boolean {
  if (a.byteLength !== b.byteLength) return false;
  for (let i = 0; i < a.byteLength; i += 1) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

const fixture: Fixture = JSON.parse(readFileSync(FIXTURE_PATH, "utf8"));

test("fixture declares the sub scope and non-empty file set", () => {
  assert.equal(fixture.schema, 1);
  assert.deepEqual(fixture.scope, ["sub"]);
  assert.ok(fixture.files.length > 0, "at least one file is pinned");
  for (const file of fixture.files) {
    assert.equal(
      file.element_ids.length,
      file.record_count,
      `${file.path} record_count matches element_ids length`,
    );
    assert.equal(
      file.byte_length,
      file.record_count * 4,
      `${file.path} byte_length is 4 bytes per element id`,
    );
    assert.equal(file.header_b64, "", `${file.path} has empty header`);
  }
});

test("src/sm18-format-write.ts exports writeSub and SUB_HISTORY_CAP", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("src/sm18-format-write.ts does not yet export writeSub");
    return;
  }
  assert.equal(typeof port.writeSub, "function");
  assert.equal(port.SUB_HISTORY_CAP, fixture.history_cap);
});

for (const file of fixture.files) {
  test(`format-write sub: ${file.path} rebuilds ${file.byte_length} bytes`, async (t) => {
    const port = await loadPort();
    if (port === null) {
      t.skip("src/sm18-format-write.ts does not yet export writeSub");
      return;
    }
    const header = decodeBase64(file.header_b64);
    const expected = decodeBase64(file.expected_bytes_b64);
    assert.equal(
      expected.byteLength,
      file.byte_length,
      `expected byte count for ${file.path}`,
    );
    const records: SubRecord[] = file.element_ids.map((element_id) => ({
      element_id,
    }));
    const produced = port.writeSub(header, records);
    assert.ok(
      bytesEqual(produced, expected),
      `${file.path} must round-trip byte for byte ` +
        `(got ${produced.byteLength} bytes, expected ${expected.byteLength})`,
    );
  });
}

test("writeSub rejects a non-empty header", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("src/sm18-format-write.ts does not yet export writeSub");
    return;
  }
  assert.throws(() => port.writeSub(new Uint8Array([0x00]), []));
});
